@@ -0,0 +1,6217 @@
+<!doctype html>
+<html lang="ja">
+<head>
+<meta charset="utf-8">
+<meta http-equiv="Content-Security-Policy" content="default-src 'none'; script-src 'sha256-ZjkdG9LeITvZZR5RoVYki9FDcNJSeg5bkwQk+Xd4HW4='; style-src 'unsafe-inline'; font-src 'none'; connect-src 'self'; img-src 'self' data:; base-uri 'none'; form-action 'none'">
+<meta name="viewport" content="width=device-width, initial-scale=1">
+<title>PR 解説</title>
+<style>
+:root {
+  --bg: #F6F5F1;
+  --panel: #FBFAF7;
+  --surface: #FFFFFF;
+  --sunken: #F1EFEA;
+  --hover: #F4F2ED;
+  --line: #E2DFD8;
+  --line-strong: #D3CFC6;
+  --track: #ECE9E2;
+  --chip: #EFEDE7;
+  --ink: #1D1F24;
+  --ink-2: #5A5E66;
+  --ink-3: #8B8F96;
+  --ink-4: #A9A59C;
+  --accent: #2F5BEA;
+  --accent-hover: #1F45C4;
+  --accent-tint: rgba(47, 91, 234, .12);
+  --accent-ring: rgba(47, 91, 234, .5);
+  --accent-glow: rgba(47, 91, 234, .25);
+  --add: #1F7A44;
+  --add-mark: #2E9D5B;
+  --mod: #8F5E00;
+  --mod-mark: #C98A12;
+  --del: #B4372D;
+  --del-mark: #D2453A;
+  --warn-tint: rgba(201, 138, 18, .14);
+  --tok-kw: #8A3FA0;
+  --tok-str: #9A5B00;
+  --tok-num: #1F6F8B;
+  --tok-com: #7E828A;
+  --tok-fn: #1F4FA3;
+  --tok-key: #1F6F8B;
+  --tok-var: #8A4307;
+  --tok-type: #1F6F8B;
+  --sans: system-ui, sans-serif;
+  --mono: ui-monospace, monospace;
+  --shadow-raised: 0 1px 2px rgba(29, 31, 36, .10);
+}
+* { box-sizing: border-box; }
+html, body { margin: 0; height: 100%; overflow: hidden; background: var(--bg); color: var(--ink); font-family: var(--sans); -webkit-font-smoothing: antialiased; }
+button { font-family: inherit; }
+a { color: var(--accent); text-decoration: none; }
+a:hover { color: var(--accent-hover); text-decoration: underline; }
+.mono { font-family: var(--mono); }
+.app { height: 100vh; display: grid; grid-template-rows: auto auto minmax(0, 1fr); grid-template-columns: minmax(0, 1fr); }
+.top { display: flex; flex-wrap: wrap; align-items: center; gap: 8px 12px; padding: 8px 14px; min-height: 52px; min-width: 0; border-bottom: 1px solid var(--line); background: var(--panel); position: relative; z-index: 20; white-space: nowrap; }
+.repo { font-family: var(--mono); font-weight: 600; font-size: 14px; flex: none; }
+.segmented { display: flex; gap: 2px; padding: 2px; background: var(--track); border-radius: 8px; flex: none; }
+/* タブの横の余白は 10px。12px だと、1280px でテストの画面の操作が 2 段目に落ちる。 */
+.segmented a { padding: 5px 10px; border-radius: 6px; font-size: 12px; font-weight: 500; color: var(--ink-2); text-decoration: none; }
+.segmented a:hover { color: var(--ink); background: rgba(255, 255, 255, .6); }
+.segmented a[aria-current="page"] { font-weight: 600; color: var(--ink); background: var(--surface); box-shadow: var(--shadow-raised); }
+/* 折り返すかどうかは基準の 240px で決め、足りない分はブランチ名を省いて詰める。auto だと、240px を超えるブランチ名の長さで段の数が変わる。 */
+.top-main { display: flex; align-items: center; gap: 10px; min-width: min(240px, 100%); flex: 1 1 240px; overflow: hidden; }
+.branch { display: block; font-family: var(--mono); font-size: 12px; font-weight: 500; color: var(--ink-2); background: var(--chip); border-radius: 6px; padding: 4px 8px; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
+.branch .arrow { color: var(--ink-3); margin: 0 6px; }
+.screen-summary { display: flex; flex: none; }
+.counts { display: flex; gap: 8px; font-family: var(--mono); font-size: 12px; flex: none; }
+.counts .total { color: var(--ink-2); }
+.add { color: var(--add); }
+.del { color: var(--del); }
+.screen-controls { display: flex; align-items: center; gap: 12px; flex: none; }
+.hint { font-size: 11px; color: var(--ink-3); }
+.links { display: flex; gap: 12px; font-size: 12px; flex: none; }
+.bands { display: flex; flex-direction: column; }
+.band { padding: 7px 14px; font-size: 12px; line-height: 1.6; color: var(--mod); background: var(--warn-tint); border-bottom: 1px solid var(--line); white-space: normal; }
+.screens { min-height: 0; position: relative; }
+.screen { height: 100%; display: grid; min-height: 0; }
+.screen[hidden] { display: none; }
+.panel { position: relative; display: flex; flex-direction: column; min-height: 0; min-width: 0; background: var(--panel); }
+.panel.is-left { border-right: 1px solid var(--line); }
+.panel.is-right { border-left: 1px solid var(--line); }
+.panel-head { display: flex; align-items: baseline; gap: 8px; padding: 14px 16px 8px; white-space: nowrap; }
+.panel-title { font-size: 12px; font-weight: 600; }
+.panel-sub { font-size: 11px; color: var(--ink-3); }
+.panel-scroll { overflow: auto; flex: 1; padding: 0 0 24px; display: flex; flex-direction: column; gap: 2px; }
+.resize-handle { position: absolute; top: 0; bottom: 0; width: 10px; cursor: col-resize; z-index: 6; display: flex; justify-content: center; touch-action: none; transition: background .15s; }
+.panel.is-left .resize-handle { right: -5px; }
+.panel.is-right .resize-handle { left: -5px; }
+.resize-handle:hover { background: rgba(47, 91, 234, .10); }
+.resize-bar { width: 2px; height: 100%; background: transparent; transition: background .15s; }
+.resize-handle.is-dragging .resize-bar { background: var(--accent); }
+.stage { overflow: auto; min-width: 0; }
+.stage-body { max-width: 1160px; margin: 0 auto; padding: 28px clamp(16px, 3vw, 36px) 96px; display: flex; flex-direction: column; gap: 30px; }
+.eyebrow { font-size: 11px; font-weight: 600; color: var(--ink-3); letter-spacing: .06em; }
+.lede { display: flex; flex-direction: column; gap: 10px; max-width: 760px; }
+.lede h1 { margin: 0; font-size: 26px; font-weight: 600; line-height: 1.4; text-wrap: pretty; }
+.lede p { margin: 0; font-size: 14.5px; line-height: 1.85; text-wrap: pretty; }
+.panel-scroll > .empty { margin: 0 12px; }
+.empty { padding: 14px 16px; border: 1px dashed var(--line-strong); border-radius: 12px; background: var(--surface); font-size: 13px; line-height: 1.75; color: var(--ink-2); }
+.section { display: flex; flex-direction: column; gap: 10px; }
+.behaviors { display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; }
+.behavior-card { display: flex; flex-direction: column; gap: 10px; padding: 14px 16px; border: 1px solid var(--line); border-radius: 12px; background: var(--sunken); }
+.behavior-card.is-after { border-color: var(--line-strong); background: var(--surface); }
+.behavior-card .card-title { font-size: 12px; font-weight: 600; color: var(--ink-2); }
+.behavior-card.is-after .card-title { color: var(--ink); }
+.row { display: flex; flex-direction: column; gap: 3px; margin: 0 8px; padding: 8px 12px; border-radius: 8px; min-width: 0; }
+.row:hover { outline: 1px solid var(--line); }
+.row.is-current { background: var(--accent-tint); box-shadow: inset 0 0 0 1px var(--accent-ring), 0 0 16px var(--accent-glow); }
+.row-title { font-size: 13px; font-weight: 500; line-height: 1.45; overflow-wrap: anywhere; }
+.row-sub { font-size: 11.5px; color: var(--ink-2); }
+.row-meta { display: flex; align-items: center; gap: 8px; font-family: var(--mono); font-size: 11px; white-space: nowrap; color: var(--ink-3); }
+.row-meta .sha { color: var(--ink-2); }
+.commit-row { display: grid; grid-template-columns: 18px minmax(0, 1fr); gap: 8px; margin: 0 8px; padding: 10px 12px 10px 8px; border-radius: 8px; }
+.commit-row:hover { outline: 1px solid var(--line); }
+.commit-rail { position: relative; }
+.commit-rail::before { content: ""; position: absolute; left: 8px; top: -12px; bottom: -12px; border-left: 1.5px solid var(--line-strong); }
+.commit-list { display: flex; flex-direction: column; gap: 2px; }
+.commit-list > .commit-row:first-child .commit-rail::before { top: 11px; }
+.commit-list > .commit-row:last-child .commit-rail::before { bottom: calc(100% - 11px); }
+.commit-dot { position: absolute; left: 3px; top: 5px; width: 12px; height: 12px; border-radius: 6px; background: var(--surface); border: 2px solid var(--ink-4); }
+.commit-body { display: flex; flex-direction: column; gap: 4px; min-width: 0; }
+.tags { display: flex; flex-wrap: wrap; gap: 4px; }
+.tag { font-size: 10.5px; color: var(--ink-2); background: var(--track); border-radius: 4px; padding: 1px 6px; }
+.tag.is-warn { font-weight: 600; color: var(--mod); background: var(--warn-tint); }
+.status { font-family: var(--mono); font-size: 10px; font-weight: 600; text-align: center; color: var(--ink-3); }
+.status[data-status="A"] { color: var(--add); }
+.status[data-status="M"], .status[data-status="R"] { color: var(--mod); }
+.status[data-status="D"] { color: var(--del); }
+.guide { max-width: 640px; margin: 12vh auto 0; padding: 28px 32px; border: 1px solid var(--line); border-radius: 12px; background: var(--surface); display: flex; flex-direction: column; gap: 12px; }
+.guide h1 { margin: 0; font-size: 20px; font-weight: 600; }
+.guide p { margin: 0; font-size: 14px; line-height: 1.8; color: var(--ink-2); }
+.prose code { font-family: var(--mono); font-size: .88em; background: var(--chip); border-radius: 4px; padding: 1px 5px; overflow-wrap: anywhere; }
+.spacer { flex: 1; }
+.muted { color: var(--ink-3); }
+.plain-button { border: none; background: transparent; font: inherit; color: inherit; text-align: left; cursor: pointer; }
+.row.overview-row { margin: 0 8px 6px; padding: 10px 12px; }
+.row.overview-row .row-title { font-weight: 600; }
+.commit-row { width: calc(100% - 16px); }
+.commit-row.is-current, .row.is-current { background: var(--accent-tint); box-shadow: inset 0 0 0 1px var(--accent-ring), 0 0 16px var(--accent-glow); }
+.commit-row.is-current .commit-dot { background: var(--accent); border-color: var(--accent); }
+[data-phase="prep"] { color: var(--ink-2); }
+[data-phase="core"] { color: var(--tok-fn); }
+[data-phase="hard"] { color: var(--mod); }
+[data-phase="revise"] { color: var(--tok-kw); }
+[data-phase="fin"] { color: var(--add); }
+.card-head { display: flex; align-items: baseline; gap: 8px; }
+.card-head .muted { font-size: 11px; font-family: var(--mono); }
+.order { display: flex; flex-direction: column; }
+.order-step { display: grid; grid-template-columns: 36px minmax(0, 1fr); gap: 12px; border-radius: 10px; padding: 0 10px; margin: 0 -10px; }
+.order-step:hover { background: var(--sunken); }
+.order-rail { position: relative; display: flex; justify-content: center; }
+.order-rail::before { content: ""; position: absolute; top: 0; bottom: 0; border-left: 1.5px solid var(--line-strong); }
+.order > .order-step:first-child .order-rail::before { top: 24px; }
+.order > .order-step:last-child .order-rail::before { bottom: calc(100% - 24px); }
+.order-num { position: relative; margin-top: 12px; width: 26px; height: 26px; border-radius: 13px; background: var(--surface); border: 1.5px solid var(--ink); display: flex; align-items: center; justify-content: center; font-family: var(--mono); font-size: 11.5px; font-weight: 600; }
+.order-body { display: flex; flex-direction: column; gap: 3px; padding: 12px 0 14px; min-width: 0; }
+.order-role { font-size: 12px; font-weight: 600; }
+.order-subject { font-size: 14.5px; font-weight: 500; line-height: 1.5; overflow-wrap: anywhere; }
+.order-why { font-size: 13px; line-height: 1.75; color: var(--ink-2); text-wrap: pretty; }
+.order-meta { font-family: var(--mono); font-size: 11px; color: var(--ink-3); }
+.section-head { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; }
+.review-count { font-size: 12px; color: var(--ink-2); }
+.review-count b { font-family: var(--mono); color: var(--ink); }
+.toggle-group { display: flex; gap: 2px; padding: 2px; background: var(--track); border-radius: 8px; }
+.toggle-group button { border: none; cursor: pointer; white-space: nowrap; padding: 4px 10px; border-radius: 6px; font-size: 12px; font-weight: 500; background: transparent; color: var(--ink-2); }
+.toggle-group button[aria-pressed="true"] { font-weight: 600; background: var(--surface); color: var(--ink); box-shadow: var(--shadow-raised); }
+.toggle-group .n { font-family: var(--mono); font-size: 10.5px; opacity: .6; margin-left: 4px; }
+.review-card { display: flex; gap: 10px; align-items: flex-start; padding: 10px 12px; border: 1px solid var(--line); border-radius: 10px; background: var(--surface); cursor: pointer; user-select: none; transition: border-color .15s, background .15s; }
+.review-card:hover { border-color: var(--ink-4); }
+.review-card.is-checked { background: var(--panel); }
+.review-card.is-checked .review-text { color: var(--ink-3); }
+.check-box { flex: none; width: 18px; height: 18px; margin-top: 2px; border-radius: 5px; border: 1.5px solid var(--ink-4); background: var(--surface); display: flex; align-items: center; justify-content: center; transition: background .15s, border-color .15s; }
+.is-checked .check-box { background: var(--accent); border-color: var(--accent); }
+.is-checked .check-box::after { content: ""; width: 4px; height: 8px; margin-top: -2px; border: solid #FFFFFF; border-width: 0 1.8px 1.8px 0; transform: rotate(45deg); }
+.review-body { display: flex; flex-direction: column; gap: 3px; min-width: 0; }
+.review-text { font-size: 13.5px; line-height: 1.7; text-wrap: pretty; }
+.review-go { align-self: flex-start; padding: 0; font-size: 11.5px; color: var(--accent); }
+.commit-head { display: flex; flex-direction: column; gap: 12px; }
+.commit-facts { display: flex; align-items: center; gap: 10px; flex-wrap: wrap; font-size: 12px; color: var(--ink-2); }
+.sha-chip { font-family: var(--mono); font-weight: 600; color: var(--ink); background: var(--track); border-radius: 5px; padding: 2px 7px; }
+.step-buttons { display: flex; gap: 6px; }
+.step-buttons button { border: 1px solid var(--line-strong); background: var(--surface); border-radius: 7px; padding: 5px 10px; font-size: 12px; cursor: pointer; color: var(--ink); }
+.step-buttons button:hover { border-color: var(--ink-4); }
+.step-buttons button:disabled { opacity: .4; cursor: default; }
+.commit-step { display: flex; align-items: center; gap: 8px; font-size: 11.5px; font-weight: 600; }
+.commit-head h1 { margin: 0; font-size: 24px; font-weight: 600; line-height: 1.4; text-wrap: pretty; overflow-wrap: anywhere; }
+.commit-message { margin: 0; padding: 12px 14px; background: var(--sunken); border-radius: 10px; font-family: var(--mono); font-size: 12.5px; line-height: 1.7; color: #3A3D44; white-space: pre-wrap; word-break: break-word; }
+.why-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(300px, 1fr)); gap: 20px 28px; align-items: start; }
+.why-text { margin: 0; font-size: 14.5px; line-height: 1.9; text-wrap: pretty; }
+.flow-chips { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; align-items: center; }
+.flow-chips .label { font-size: 11.5px; color: var(--ink-3); }
+.flow-chip { display: flex; align-items: center; gap: 4px; font-size: 12px; color: var(--ink); background: var(--surface); border: 1px solid var(--line-strong); border-radius: 999px; padding: 3px 10px; }
+.flow-chip:hover { color: var(--ink); border-color: var(--ink-4); text-decoration: none; }
+.flow-chip .arrow { color: var(--ink-3); }
+.behavior-item { display: flex; gap: 8px; font-size: 13.5px; line-height: 1.7; }
+.behavior-item .mark { color: var(--ink-3); }
+.behavior-card.is-after .behavior-item .mark { color: var(--add-mark); }
+.behavior-body { display: flex; flex-direction: column; gap: 5px; min-width: 0; }
+.behavior-none { font-size: 13px; color: var(--ink-3); }
+.message-chip { display: flex; align-items: center; gap: 6px; flex-wrap: wrap; }
+.kind { font-size: 10.5px; font-weight: 600; padding: 1px 6px; border-radius: 4px; border: 1px solid var(--line); }
+[data-kind="cmd"] { --kind-bg: #E3EDFC; --kind-line: #B5CDF3; --kind-ink: #1F4FA3; }
+[data-kind="qry"] { --kind-bg: #EEE8FA; --kind-line: #D2C4F0; --kind-ink: #55369F; }
+[data-kind="evt"] { --kind-bg: #FDEBD6; --kind-line: #F2C690; --kind-ink: #8A4307; }
+.kind[data-kind], .label-chip[data-kind] { background: var(--kind-bg); border-color: var(--kind-line); color: var(--kind-ink); }
+.message-name { font-size: 12px; font-weight: 600; }
+.behavior-card:not(.is-after) .message-name { font-weight: 500; text-decoration: line-through; color: var(--ink-2); }
+.message-route { font-size: 11.5px; color: var(--ink-3); }
+.code-head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; }
+.code-head .hint { font-size: 11.5px; }
+.text-button { padding: 2px 4px; font-size: 12px; color: var(--ink-2); }
+.text-button:hover { color: var(--ink); }
+.file-card { border: 1px solid var(--line); border-radius: 12px; background: var(--surface); overflow: hidden; }
+.file-card.is-sent { border-color: var(--accent-ring); }
+.file-sent-note { padding: 6px 14px; font-size: 11.5px; font-weight: 600; color: var(--accent); background: var(--accent-tint); border-bottom: 1px solid var(--chip); }
+.file-card > summary { display: flex; align-items: center; gap: 10px; padding: 10px 14px; background: var(--panel); cursor: pointer; white-space: nowrap; min-width: 0; list-style: none; }
+.file-card > summary::-webkit-details-marker { display: none; }
+.file-card > summary:hover { background: var(--hover); }
+.file-card[open] > summary { border-bottom: 1px solid var(--chip); }
+.chev { flex: none; width: 6px; height: 6px; margin: 0 2px; border-right: 1.4px solid var(--ink-2); border-bottom: 1.4px solid var(--ink-2); transform: rotate(-45deg); transition: transform .15s; }
+.file-card[open] .chev { transform: rotate(45deg); }
+.file-card .status { font-size: 11px; flex: none; }
+.file-path { font-family: var(--mono); font-size: 12.5px; font-weight: 500; overflow: hidden; text-overflow: ellipsis; min-width: 0; }
+.file-card[data-status="D"] .file-path { text-decoration: line-through; }
+.concept-chip { font-size: 11px; color: var(--ink-2); background: var(--track); border-radius: 4px; padding: 1px 6px; flex: none; }
+.file-counts { font-family: var(--mono); font-size: 11.5px; flex: none; }
+.file-omit { padding: 12px 16px; font-size: 13px; line-height: 1.7; color: var(--ink-2); background: var(--sunken); }
+.file-omit.is-deleted { background: rgba(210, 69, 58, .05); }
+.hunk-head { font-family: var(--mono); font-size: 11.5px; color: var(--ink-3); background: var(--hover); padding: 4px 14px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
+.hunk { display: flex; flex-wrap: wrap; align-items: stretch; }
+.hunk-code { flex: 1 1 520px; min-width: 0; overflow-x: auto; padding: 4px 0; font-family: var(--mono); font-size: 12.5px; line-height: 21px; }
+.hunk-notes { flex: 1 1 260px; min-width: 0; padding: 10px 14px 12px; display: flex; flex-direction: column; gap: 8px; background: #FCFBF8; }
+.code-line { display: grid; grid-template-columns: 40px 40px 32px 16px max-content; min-width: max-content; transition: background .15s; }
+.hunk-code.is-code .code-line { grid-template-columns: 44px 32px 3px 14px max-content; }
+.code-line .ln { color: var(--ink-4); text-align: right; padding-right: 8px; user-select: none; overflow: hidden; }
+.code-line .marks { display: flex; align-items: center; gap: 2px; padding-left: 4px; }
+.marker { width: 16px; height: 16px; border-radius: 8px; background: var(--ink); color: #FFFFFF; font-family: var(--sans); font-size: 10px; font-weight: 600; display: flex; align-items: center; justify-content: center; transition: background .15s; }
+.code-line .sign { text-align: center; user-select: none; }
+.code-line[data-sign="+"] { background: rgba(46, 157, 91, .10); }
+.code-line[data-sign="+"] .sign { color: var(--add); }
+.code-line[data-sign="-"] { background: rgba(210, 69, 58, .09); }
+.code-line[data-sign="-"] .sign { color: var(--del); }
+.code-line[data-sign="-"] .code-text { color: #6B4B47; }
+.hunk-code.is-code .code-line[data-sign="+"] { background: rgba(46, 157, 91, .045); }
+.code-line.is-gap { background: rgba(210, 69, 58, .05); }
+.code-line .bar { position: relative; }
+.code-line .bar.is-on::before { content: ""; position: absolute; left: 0; right: 0; top: 0; bottom: 0; background: var(--add-mark); }
+.code-line .bar.is-start::before { top: 4px; border-top-left-radius: 2px; border-top-right-radius: 2px; }
+.code-line .bar.is-end::before { bottom: 4px; border-bottom-left-radius: 2px; border-bottom-right-radius: 2px; }
+.code-text { white-space: pre; padding-right: 16px; }
+.code-line.is-lit, .code-line.is-sent { background: rgba(47, 91, 234, .14); box-shadow: inset 3px 0 0 var(--accent); }
+.code-line.is-lit .bar.is-on::before, .code-line.is-sent .bar.is-on::before, .marker.is-lit { background: var(--accent); }
+.note { display: flex; gap: 9px; align-items: flex-start; padding: 9px 11px; border-radius: 9px; background: var(--surface); border: 1px solid var(--line); transition: background .15s, border-color .15s; }
+.note.is-lit { background: rgba(47, 91, 234, .08); border-color: var(--accent-ring); }
+.note-badge { flex: none; width: 18px; height: 18px; margin-top: 1px; border-radius: 9px; background: var(--ink); color: #FFFFFF; font-size: 10.5px; font-weight: 600; display: flex; align-items: center; justify-content: center; }
