+            async function readPublishedMap(folder) {
+              try {
+                const index = await fs.lstat(path.join(folder, 'index.html'));
+                const mapFile = await fs.lstat(path.join(folder, 'change-map.json'));
+                if (!index.isFile() || !mapFile.isFile()) {
+                  return null;
